#include <bits/stdc++.h>
using namespace std;

struct CharacterInfo {
    char chr;
    int val;
    int idx;
    CharacterInfo(char c, int v, int i) : chr(c), val(v), idx(i) {}
};

void swap_chars(vector<char>& chars, vector<int>& vals, int i) {
    char tempChar = chars[i];
    chars[i] = chars[chars.size() - i - 1];
    chars[chars.size() - i - 1] = tempChar;

    int tempVal = vals[i];
    vals[i] = vals[vals.size() - i - 1];
    vals[vals.size() - i - 1] = tempVal;
}

bool isAntiPalindrome(const vector<char>& chars) {
    int len = (int)chars.size();
    for (int i = 0; i < len / 2; i++) {
        if (chars[i] == chars[len - i - 1]) {
            return false;
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    cin.ignore();
    string line;
    getline(cin, line);
    line.erase(line.begin(), find_if(line.begin(), line.end(), [](int ch){ return !isspace(ch); }));
    vector<char> characters(line.begin(), line.end());

    vector<int> values(n);
    for (int i = 0; i < n; i++) {
        cin >> values[i];
    }
    cin.ignore();

    vector<CharacterInfo> mismatchedChars;
    vector<CharacterInfo> charList;

    for (int i = 0; i < n / 2; i++) {
        if (values[i] > values[n - i - 1]) {
            swap_chars(characters, values, i);
        }
        CharacterInfo ci(characters[i], values[i], i);
        if (characters[i] == characters[n - i - 1]) {
            mismatchedChars.push_back(ci);
        }
        charList.push_back(ci);
    }

    sort(charList.begin(), charList.end(), [](const CharacterInfo& a, const CharacterInfo& b) {
        return a.val < b.val;
    });

    int totalDiff = 0;
    if (!isAntiPalindrome(characters)) {
        if (mismatchedChars.size() == 1) {
            CharacterInfo wrongChar = mismatchedChars[0];
            for (const auto& ci : charList) {
                if (ci.chr != wrongChar.chr && characters[n - ci.idx - 1] != wrongChar.chr) {
                    totalDiff = wrongChar.val + ci.val;
                    break;
                }
            }
        } else if (mismatchedChars.size() > 1) {
            unordered_map<char, int> countMap;
            for (const auto& ci : mismatchedChars) {
                countMap[ci.chr]++;
            }
            int maxCount = 0;
            for (const auto& kv : countMap) {
                if (kv.second > maxCount) {
                    maxCount = kv.second;
                }
            }
            vector<CharacterInfo> appendList;
            while (maxCount * 2 > (int)mismatchedChars.size() + (int)appendList.size()) {
                auto maxEntry = max_element(countMap.begin(), countMap.end(), [](const pair<char,int>& a, const pair<char,int>& b){
                    return a.second < b.second;
                });
                char maxChar = maxEntry->first;
                for (const auto& ci : charList) {
                    if (ci.chr != maxChar && characters[n - ci.idx - 1] != maxChar && 
                        find_if(mismatchedChars.begin(), mismatchedChars.end(), [&](const CharacterInfo& c){ return c.chr == ci.chr; }) == mismatchedChars.end() &&
                        find_if(appendList.begin(), appendList.end(), [&](const CharacterInfo& c){ return c.chr == ci.chr; }) == appendList.end()) {
                        appendList.push_back(ci);
                        break;
                    }
                }
                // Recompute maxCount
                countMap[maxChar]++;
                maxCount = 0;
                for (const auto& kv : countMap) {
                    if (kv.second > maxCount) {
                        maxCount = kv.second;
                    }
                }
            }
            int sumMismatched = 0;
            for (const auto& c : mismatchedChars) sumMismatched += c.val;
            int sumAppend = 0;
            for (const auto& c : appendList) sumAppend += c.val;
            totalDiff = sumMismatched + sumAppend;
        }
    }
    int sumValues = accumulate(values.begin(), values.end(), 0);
    cout << sumValues - totalDiff << "\n";

    return 0;
}
